/* Each word sits in a clip box one line tall and rises from just under it (1.1em, the
   original's 66px at 60px type) as the heading crosses the lower half of the window. Word n
   starts and ends a little later than word n-1, so the last words trail the scroll. */
.rho-heading-clip {
  display: inline-block;
  overflow: clip;
  vertical-align: top;
  /* room for descenders under the tight line-height */
  padding-bottom: 0.14em;
  margin-bottom: -0.14em;
}
.rho-heading-word {
  display: inline-block;
}

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .rho-heading-word {
      animation: rho-heading-rise linear both;
      animation-timeline: view();
      animation-range: cover calc(6% + var(--rho-word, 0) * 1.2%) cover calc(26% + var(--rho-word, 0) * 2%);
    }
  }
}

@keyframes rho-heading-rise {
  from { transform: translateY(1.1em); }
  to { transform: translateY(0); }
}

import { Fragment, type CSSProperties } from "react";
import { cn } from "@foundry/foundry-utils";
import "./rho-heading.css";

export interface RhoHeadingProps {
  /** the heading text; it is split into words for the reveal */
  text: string;
  /** which heading element to render */
  as?: "h1" | "h2" | "h3";
  /** section: 36px phones / 60px desktop · hero: 48px / 80px */
  size?: "section" | "hero";
  /** words rise into place on scroll (default true) */
  reveal?: boolean;
  className?: string;
}

const sizes = {
  section: "text-[2.25rem] leading-none lg:text-[3.75rem]",
  hero: "text-[3rem] leading-[1.1] lg:text-[5rem]",
};

export function RhoHeading({ text, as: Tag = "h2", size = "section", reveal = true, className }: RhoHeadingProps) {
  const words = text.split(/\s+/).filter(Boolean);
  return (
    <Tag className={cn("font-display font-normal tracking-[-0.01em] text-balance text-foreground", sizes[size], className)}>
      {reveal ? (
        <>
          <span className="sr-only">{text}</span>
          <span aria-hidden="true">
            {words.map((word, i) => (
              <Fragment key={i}>
                <span className="rho-heading-clip">
                  <span className="rho-heading-word" style={{ "--rho-word": i } as CSSProperties}>
                    {word}
                  </span>
                </span>
                {i < words.length - 1 && " "}
              </Fragment>
            ))}
          </span>
        </>
      ) : (
        text
      )}
    </Tag>
  );
}
